mapper.select:
SELECT 
  FROM gw_eval e
  JOIN gw_eval_period p ON p.period_id = e.period_id
  JOIN gw_user ue ON ue.user_id = e.evaluatee_id
  JOIN gw_user ur ON ur.user_id = e.evaluator_id
  LEFT JOIN gw_dept de ON de.dept_id = ue.dept_id
 WHERE e.period_id = #{periodId}
   AND e.evaluatee_id = #{evaluateeId}
   AND e.evaluator_id = #{evaluatorId}
